\pset tuples_only on
\pset format unaligned
SELECT jsonb_build_object('section','audit','at',clock_timestamp(),'session_readonly',current_setting('default_transaction_read_only'),'transaction_readonly',current_setting('transaction_read_only'));
SELECT jsonb_build_object('section','schema','table',table_name,'columns',jsonb_agg(column_name ORDER BY ordinal_position)) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('pkg_packing_records','pkg_work_shifts','pkg_handover_records','pkg_label_print_logs','inv_batches','inv_ledger','wms_inbound','wms_locations') GROUP BY table_name;
SELECT jsonb_build_object('section','packing','row',jsonb_build_object('id',to_jsonb(x)->'id','code',to_jsonb(x)->'code','status',to_jsonb(x)->'status','is_test',to_jsonb(x)->'is_test','shift_id',to_jsonb(x)->'shift_id','grading_code',to_jsonb(x)->'grading_code','grading_codes_json',to_jsonb(x)->'grading_codes_json','batches_json',to_jsonb(x)->'batches_json','production_date',to_jsonb(x)->'production_date','total_eggs',to_jsonb(x)->'total_eggs','total_boxes',to_jsonb(x)->'total_boxes','operator_name',to_jsonb(x)->'operator_name','created_at',to_jsonb(x)->'created_at','updated_at',to_jsonb(x)->'updated_at')) FROM pkg_packing_records x WHERE id=33;
SELECT jsonb_build_object('section','shift','row',jsonb_build_object('id',to_jsonb(x)->'id','code',to_jsonb(x)->'code','shift_code',to_jsonb(x)->'shift_code','site_id',to_jsonb(x)->'site_id','production_date',to_jsonb(x)->'production_date','status',to_jsonb(x)->'status','is_test',to_jsonb(x)->'is_test','operator_id',to_jsonb(x)->'operator_id','operator_name',to_jsonb(x)->'operator_name','supervisor_name',to_jsonb(x)->'supervisor_name','opened_at',to_jsonb(x)->'opened_at','closed_at',to_jsonb(x)->'closed_at','created_at',to_jsonb(x)->'created_at')) FROM pkg_work_shifts x WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','farm','row',jsonb_build_object('farm_code',to_jsonb(x)->'farm_code','farm_name',to_jsonb(x)->'farm_name','company_code',to_jsonb(x)->'company_code','status',to_jsonb(x)->'status')) FROM brd_farms x WHERE farm_code=(SELECT site_id FROM pkg_work_shifts WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33));
SELECT jsonb_build_object('section','batches','row',jsonb_build_object('id',to_jsonb(x)->'id','batch_no',to_jsonb(x)->'batch_no','source_type',to_jsonb(x)->'source_type','source_no',to_jsonb(x)->'source_no','packaging_batch_ref',to_jsonb(x)->'packaging_batch_ref','collection_ref',to_jsonb(x)->'collection_ref','product_code',to_jsonb(x)->'product_code','sku_code',to_jsonb(x)->'sku_code','grade_code',to_jsonb(x)->'grade_code','grade_code_std',to_jsonb(x)->'grade_code_std','spec_code',to_jsonb(x)->'spec_code','company_code',to_jsonb(x)->'company_code','warehouse_code',to_jsonb(x)->'warehouse_code','location_code',to_jsonb(x)->'location_code','qty',to_jsonb(x)->'qty','qty_available',to_jsonb(x)->'qty_available','qty_reserved',to_jsonb(x)->'qty_reserved','egg_date',to_jsonb(x)->'egg_date','inbound_date',to_jsonb(x)->'inbound_date','status',to_jsonb(x)->'status','created_at',to_jsonb(x)->'created_at')) FROM inv_batches x WHERE packaging_batch_ref=(SELECT code FROM pkg_packing_records WHERE id=33) OR source_no=(SELECT code FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','ledger','row',jsonb_build_object('id',to_jsonb(x)->'id','batch_no',to_jsonb(x)->'batch_no','change_type',to_jsonb(x)->'change_type','qty_change',to_jsonb(x)->'qty_change','qty_before',to_jsonb(x)->'qty_before','qty_after',to_jsonb(x)->'qty_after','ref_no',to_jsonb(x)->'ref_no','sku_code',to_jsonb(x)->'sku_code','company_code',to_jsonb(x)->'company_code','warehouse_code',to_jsonb(x)->'warehouse_code','location_code',to_jsonb(x)->'location_code','created_at',to_jsonb(x)->'created_at')) FROM inv_ledger x WHERE ref_no=(SELECT code FROM pkg_packing_records WHERE id=33) OR batch_no=(SELECT code FROM pkg_packing_records WHERE id=33) OR batch_no IN (SELECT batch_no FROM inv_batches WHERE packaging_batch_ref=(SELECT code FROM pkg_packing_records WHERE id=33) OR source_no=(SELECT code FROM pkg_packing_records WHERE id=33));
SELECT jsonb_build_object('section','handover','row',jsonb_build_object('id',to_jsonb(x)->'id','code',to_jsonb(x)->'code','shift_id',to_jsonb(x)->'shift_id','packing_code',to_jsonb(x)->'packing_code','boxes_json',to_jsonb(x)->'boxes_json','box_count',to_jsonb(x)->'box_count','pallet_code',to_jsonb(x)->'pallet_code','location',to_jsonb(x)->'location','receiver',to_jsonb(x)->'receiver','production_date',to_jsonb(x)->'production_date','status',to_jsonb(x)->'status','received_at',to_jsonb(x)->'received_at','received_by',to_jsonb(x)->'received_by','created_at',to_jsonb(x)->'created_at')) FROM pkg_handover_records x WHERE packing_code=(SELECT code FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','labels','row',jsonb_build_object('id',to_jsonb(x)->'id','packing_code',to_jsonb(x)->'packing_code','print_type',to_jsonb(x)->'print_type','packaging_batch_id',to_jsonb(x)->'packaging_batch_id','box_code',to_jsonb(x)->'box_code','boxes_json',to_jsonb(x)->'boxes_json','print_qty',to_jsonb(x)->'print_qty','print_count',to_jsonb(x)->'print_count','printed_at',to_jsonb(x)->'printed_at','created_at',to_jsonb(x)->'created_at')) FROM pkg_label_print_logs x WHERE to_jsonb(x)->>'packaging_batch_id'=(SELECT code FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','sku','row',jsonb_build_object('id',to_jsonb(x)->'id','sku_code',to_jsonb(x)->'sku_code','product_code',to_jsonb(x)->'product_code','grade_code',to_jsonb(x)->'grade_code','spec_code',to_jsonb(x)->'spec_code','status',to_jsonb(x)->'status')) FROM product_skus x WHERE grade_code='GRADE_5' AND spec_code='PKG_PACK_SPEC_3';
SELECT jsonb_build_object('section','product','row',jsonb_build_object('id',to_jsonb(x)->'id','product_code',to_jsonb(x)->'product_code','product_name',to_jsonb(x)->'product_name','product_name_zh',to_jsonb(x)->'product_name_zh','status',to_jsonb(x)->'status','has_grade',to_jsonb(x)->'has_grade','has_spec',to_jsonb(x)->'has_spec')) FROM mst_products x WHERE product_code='EGG';
SELECT jsonb_build_object('section','grade','row',jsonb_build_object('grade_code',to_jsonb(x)->'grade_code','grade_name',to_jsonb(x)->'grade_name','grade_name_zh',to_jsonb(x)->'grade_name_zh','status',to_jsonb(x)->'status','is_saleable',to_jsonb(x)->'is_saleable','is_storable',to_jsonb(x)->'is_storable')) FROM product_grades x WHERE grade_code='GRADE_5';
SELECT jsonb_build_object('section','spec','row',jsonb_build_object('spec_code',to_jsonb(x)->'spec_code','spec_name',to_jsonb(x)->'spec_name','qty_per_unit',to_jsonb(x)->'qty_per_unit','status',to_jsonb(x)->'status')) FROM packaging_specs x WHERE spec_code='PKG_PACK_SPEC_3';
SELECT jsonb_build_object('section','mode','row',jsonb_build_object('scope_level',to_jsonb(x)->'scope_level','scope_code',to_jsonb(x)->'scope_code','mode',to_jsonb(x)->'mode')) FROM inv_source_mode x WHERE scope_level='GROUP' OR scope_code IN ((SELECT site_id FROM pkg_work_shifts WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33)),(SELECT company_code FROM brd_farms WHERE farm_code=(SELECT site_id FROM pkg_work_shifts WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33))));
SELECT jsonb_build_object('section','warehouse_candidates','row',jsonb_build_object('warehouse_code',to_jsonb(x)->'warehouse_code','warehouse_name',to_jsonb(x)->'warehouse_name','company_code',to_jsonb(x)->'company_code','status',to_jsonb(x)->'status','manager_id',to_jsonb(x)->'manager_id','manager_name',to_jsonb(x)->'manager_name')) FROM wms_warehouses x WHERE company_code=(SELECT company_code FROM brd_farms WHERE farm_code=(SELECT site_id FROM pkg_work_shifts WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33)));
SELECT jsonb_build_object('section','location_candidates','row',jsonb_build_object('location_code',to_jsonb(x)->'location_code','location_name',to_jsonb(x)->'location_name','warehouse_code',to_jsonb(x)->'warehouse_code','zone_code',to_jsonb(x)->'zone_code','status',to_jsonb(x)->'status')) FROM wms_locations x WHERE warehouse_code IN (SELECT warehouse_code FROM wms_warehouses WHERE company_code=(SELECT company_code FROM brd_farms WHERE farm_code=(SELECT site_id FROM pkg_work_shifts WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33))));
SELECT jsonb_build_object('section','shift_handover','row',jsonb_build_object('id',to_jsonb(x)->'id','code',to_jsonb(x)->'code','packing_code',to_jsonb(x)->'packing_code','box_count',to_jsonb(x)->'box_count','location',to_jsonb(x)->'location','receiver',to_jsonb(x)->'receiver','production_date',to_jsonb(x)->'production_date','created_at',to_jsonb(x)->'created_at')) FROM pkg_handover_records x WHERE shift_id=(SELECT shift_id FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','sources','row',jsonb_build_object('grading_code',g.code,'grading_status',g.status,'grading_is_test',g.is_test,'source_id',s.id,'batch_code',s.batch_code,'house_code',s.house_code,'source_status',s.batch_status,'source_is_test',s.is_test,'shift_id',s.shift_id,'production_date',s.production_date,'received_qty',s.received_qty,'farm_code',h.farm_code))
FROM pkg_grading_records g JOIN pkg_grading_source_links l ON l.grading_id=g.id JOIN pkg_source_batches s ON s.id=l.source_batch_id LEFT JOIN brd_houses h ON h.house_code=s.house_code
WHERE g.code IN (SELECT grading_code FROM pkg_packing_records WHERE id=33 UNION SELECT jsonb_array_elements_text(grading_codes_json) FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','shift_summary','shift_id',w.id,'date',w.production_date,'status',w.status,'is_test',w.is_test,
 'packed_boxes',(SELECT COALESCE(sum(total_boxes),0) FROM pkg_packing_records WHERE shift_id=w.id AND status='ACTIVE' AND is_test=w.is_test),
 'packed_eggs',(SELECT COALESCE(sum(total_eggs),0) FROM pkg_packing_records WHERE shift_id=w.id AND status='ACTIVE' AND is_test=w.is_test),
 'warehoused_boxes',(SELECT COALESCE(sum(box_count),0) FROM pkg_handover_records WHERE shift_id=w.id AND production_date=w.production_date),
 'warehoused_pallets',(SELECT count(DISTINCT NULLIF(pallet_code,'')) FROM pkg_handover_records WHERE shift_id=w.id AND production_date=w.production_date),
 'label_count',(SELECT count(*) FROM pkg_label_print_logs l JOIN pkg_packing_records p ON p.code=l.packaging_batch_id WHERE p.shift_id=w.id AND p.status='ACTIVE' AND p.is_test=w.is_test AND DATE(l.printed_at)=w.production_date))
FROM pkg_work_shifts w WHERE id=(SELECT shift_id FROM pkg_packing_records WHERE id=33);
SELECT jsonb_build_object('section','end','at',clock_timestamp());
